{
  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "flip",
  "supportive_card_ids": ["C196", "C217", "C221", "C155", "C170"],
  "contradictory_card_ids": ["C144", "C128", "C01", "C04", "C17", "C21"],
  "prediction_basis_card_ids": ["C196", "C217", "C221"],
  "claims": [
    {
      "claim": "L5 loperamide records show strong P-gp efflux: pH-gradient efflux ratio 18.42 and verapamil-sensitive apical-to-basolateral increase to 45.4 versus basolateral-to-apical 18.7 x10^-6 cm/s. The query shares loperamide's tertiary diphenylacetamide and basic amino-alcohol scaffold, so this is transferable mechanistic evidence for gut-wall efflux and presystemic loss.",
      "card_ids": ["C196", "C217", "C221"]
    },
    {
      "claim": "L5 high-permeability no-efflux records for trihexyphenidyl and tetrahydropalmatine lack the tertiary amide and are less structurally relevant. They do not outweigh the loperamide efflux evidence.",
      "card_ids": ["C176", "C208"]
    },
    {
      "claim": "L1 transferable F values above 20% come from less similar scaffolds such as diphenhydramine, trimipramine, dapoxetine, and milnacipran. They do not establish F >= 20% for this loperamide-like amide.",
      "card_ids": ["C01", "C04", "C17", "C21"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "contradictory",
      "decision_effect": "changed",
      "card_ids": ["C196", "C217", "C221"]
    }
  ],
  "evidence_gaps": [
    "No direct oral F measurement for the query in any level.",
    "No query-specific efflux or intestinal metabolism data; loperamide transfer is structural analogy.",
    "No first-pass hepatic metabolism data for the tertiary amide.",
    "Solubility and dissolution for the low neutral fraction 0.28 are unmeasured."
  ],
  "decision_summary": "Flip to low. L5 loperamide efflux records provide coherent, transferable gut-wall efflux evidence for a close structural analogue, supporting F < 20%. High permeability alone is insufficient because efflux can limit absorption. Confidence is moderate because no direct query PK exists and structural differences remain."
}

